/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_sessionFill();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil51320n2.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "img_92", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '1'); } }, { id: "img_94", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '2'); } }, { id: "img_96", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '3'); } }, { id: "img_98", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '4'); } }, { id: "img_100", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '6'); } }, { id: "c_otherwise_101", fn: function(){ return (!(((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '1') || ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '2') || ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '3') || ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '4') || ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '6'))); } }, { id: "if_attachFileNm", fn: function(){ return (!(String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "tr_86", fn: function(){ return (!(String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "c_when_63", fn: function(){ return ((dlt_bbsList.getCellData(0, "quesAnsTpCd") ?? (() => { throw new Error("unresolved:" + "entity.quesAnsTpCd"); })()) === '1'); } }, { id: "img_122", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '1'); } }, { id: "img_124", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '2'); } }, { id: "img_126", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '3'); } }, { id: "img_128", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '4'); } }, { id: "img_130", fn: function(){ return ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '6'); } }, { id: "c_otherwise_131", fn: function(){ return (!(((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '1') || ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '2') || ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '3') || ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '4') || ((dlt_bbsList.getCellData(0, "attachIcon") ?? (() => { throw new Error("unresolved:" + "entity.attachIcon"); })()) === '6'))); } }, { id: "if_attachFileNm_2", fn: function(){ return (!(String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "tr_116", fn: function(){ return (!(String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "c_when_104", fn: function(){ return ((dlt_bbsList.getCellData(0, "quesAnsTpCd") ?? (() => { throw new Error("unresolved:" + "entity.quesAnsTpCd"); })()) === '2'); } }, { id: "btn_modify", fn: function(){ return ((((dma_pageContext.get("bbsList") ?? "")) && typeof ((dma_pageContext.get("bbsList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("bbsList") ?? "")).getRowCount() : ((((dma_pageContext.get("bbsList") ?? "")) == null) ? 0 : (((dma_pageContext.get("bbsList") ?? "")).length || 0))) === 1 && (dlt_bbsList.getCellData(0, "quesAnsTpCd") ?? (() => { throw new Error("unresolved:" + "entity.quesAnsTpCd"); })()) === '1' && (dlt_bbsList.getCellData(0, "isurCd") ?? (() => { throw new Error("unresolved:" + "entity.isurCd"); })()) === (dma_session.get("isurCd") ?? (() => { throw new Error("unresolved:" + "session.company.isurCd"); })())); } }, { id: "btn_delete", fn: function(){ return ((((dma_pageContext.get("bbsList") ?? "")) && typeof ((dma_pageContext.get("bbsList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("bbsList") ?? "")).getRowCount() : ((((dma_pageContext.get("bbsList") ?? "")) == null) ? 0 : (((dma_pageContext.get("bbsList") ?? "")).length || 0))) === 1 && (dlt_bbsList.getCellData(0, "quesAnsTpCd") ?? (() => { throw new Error("unresolved:" + "entity.quesAnsTpCd"); })()) === '1' && (dlt_bbsList.getCellData(0, "isurCd") ?? (() => { throw new Error("unresolved:" + "entity.isurCd"); })()) === (dma_session.get("isurCd") ?? (() => { throw new Error("unresolved:" + "session.company.isurCd"); })())); } }, { id: "c_when_58", fn: function(){ return (!(String(((dma_pageContext.get("bbsList") ?? "")) == null ? '' : ((dma_pageContext.get("bbsList") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_60", entity: "dlt_bbsList", countIds: [], rowConds: [{"childId":"c_if_147","kind":"last"}], cells: [{ childId: "__rc2", fn: function (v, i) { return String(v("comNm")); } }, { childId: "__rc3", fn: function (v, i) { return String(v("wrtrNm")); } }, { childId: "__rc4", fn: function (v, i) { return String(v("regDdtm")); } }, { childId: "__rc5", fn: function (v, i) { return String(v("contnTitle")); } }, { childId: "__rc6", fn: function (v, i) { return String(v("contnContn")); } }, { childId: "__rc7", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc8", fn: function (v, i) { return " " + String(v("contnTitle")); } }, { childId: "__rc9", fn: function (v, i) { return String(v("contnContn")); } }, { childId: "__rc10", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc11", fn: function (v, i) { return String(v("wrtrNm")) + " ("; } }, { childId: "__rc12", fn: function (v, i) { return String(v("regTelNo")) + ")"; } }, { childId: "__rc13", fn: function (v, i) { return String(v("regDdtm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(dma_basicComInfo.get("comNm")) + " (" + String(dma_basicComInfo.get("isurCd")) + " : " + String(dma_basicComInfo.get("mktTpNm")) + ")"; } },
        { childId: "__rb1", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["usrId"] ?? "") + " / " + String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["corpUsrNm"] ?? ""); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// 세션 사용자 결선 (어휘 session_attribute 2건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId","corpUsrNm"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil51320n2' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 2개다(tx_fn_delete, tx_fn_PrelistPageSearch) — 어느 것이 «열자마자» 인지 정할 근거가 없다

