/**
 * @method
 * @name tx_fn_FileDown
 * @description File Down 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FileDown = async function (action) {
    try { return await $c.data.downFile(action ?? "/listInvstg/filedown.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name goList
 * @description go List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goList = async function () {
    $c.util.getComponent('dma_goListReq').set('method', 'searchCommentLetterList');
    $c.util.getComponent('dma_goListReq').set('page', '30');
    const nr = await scwin.tx_fn_goList('bbs.do');
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/ui/jsp/JLDFIL51300.xml", { "method": 'searchCommentLetterList', "page": '30' });
    }
};

