/**
 * @method
 * @name prelistPageSearch
 * @description prelist Page Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.prelistPageSearch = async function () {
    let action;
    const gongmo = $c.util.getComponent('dma_goListReq').get('gongMo');
    action = 'listPrelmInvstg.do';
    $c.util.getComponent('dma_goListReq').set('method', "listPrelmInvstgList");
    if (gongmo === "Y") {
        $c.util.getComponent('dma_goListReq').set('page', "konexGongsamo");
    } else {
        $c.util.getComponent('dma_goListReq').set('page', "konex");
    }
    await scwin.tx_fn_PrelistPageSearch(action);
};
